with src as (select * from order_items where quantity < 5 and (product_id = 39 or product_id in (4, 25, 28, 29))), summary as (select product_id, case when quantity >= 8 then 'high' when quantity >= 2 then 'mid' else 'low' end as quantity_bucket, max(unit_price) - min(unit_price) as unit_price_range from src group by product_id, case when quantity >= 8 then 'high' when quantity >= 2 then 'mid' else 'low' end) select product_id, quantity_bucket, unit_price_range from summary
